<?php
require_once __DIR__ . '/includes/bootstrap.php';
riderRequireLogin(); ensureMisTables();
$conn = dbConnect(); $riderId = (int) $_SESSION['rider_id'];
$page = max(1, (int) ($_GET['page'] ?? 1)); $perPage = 12; $offset = ($page - 1) * $perPage;
$status = $_GET['status'] ?? 'all'; if (!in_array($status, array('all','delivered','failed'), true)) $status = 'all';
$filter = $status === 'all' ? "a.status IN ('delivered','failed')" : "a.status='" . mysqli_real_escape_string($conn, $status) . "'";
$count = mysqli_prepare($conn, "SELECT COUNT(*) total FROM order_delivery_assignments a WHERE a.rider_id=? AND $filter"); mysqli_stmt_bind_param($count, 'i', $riderId); mysqli_stmt_execute($count); $total = (int)(mysqli_fetch_assoc(mysqli_stmt_get_result($count))['total'] ?? 0);
$sql = "SELECT a.orderid,a.status,a.assigned_at,a.accepted_at,a.delivered_at,a.failure_reason,o.name customer_name,o.address,p.payment_method,f.total_amount,c.status collection_status FROM order_delivery_assignments a JOIN orders o ON o.orderid=a.orderid LEFT JOIN order_payments p ON p.orderid=o.orderid LEFT JOIN order_financials f ON f.orderid=o.orderid LEFT JOIN cod_collections c ON c.orderid=a.orderid WHERE a.rider_id=? AND $filter ORDER BY COALESCE(a.delivered_at,a.assigned_at) DESC LIMIT ? OFFSET ?";
$stmt = mysqli_prepare($conn, $sql); mysqli_stmt_bind_param($stmt, 'iii', $riderId, $perPage, $offset); mysqli_stmt_execute($stmt); $deliveries = mysqli_fetch_all(mysqli_stmt_get_result($stmt), MYSQLI_ASSOC);
$summary = mysqli_prepare($conn, "SELECT SUM(status='delivered') delivered,SUM(status='failed') failed,AVG(CASE WHEN status='delivered' AND accepted_at IS NOT NULL AND delivered_at IS NOT NULL THEN TIMESTAMPDIFF(MINUTE,accepted_at,delivered_at) END) average_minutes FROM order_delivery_assignments WHERE rider_id=?"); mysqli_stmt_bind_param($summary, 'i', $riderId); mysqli_stmt_execute($summary); $stats = mysqli_fetch_assoc(mysqli_stmt_get_result($summary)) ?: array('delivered'=>0,'failed'=>0,'average_minutes'=>null);
$pages = max(1, (int)ceil($total / $perPage)); $title = $status === 'failed' ? 'Reported delivery issues' : ($status === 'delivered' ? 'Completed deliveries' : 'Delivery history');
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="theme-color" content="#ff4b1f"><title>Delivery history | Foodera</title><link rel="icon" type="image/png" href="../assets/branding/foodera-icon.png"><link rel="stylesheet" href="https://cdn.jsdelivr.net/npm/bootstrap-icons@1.11.3/font/bootstrap-icons.min.css"><link rel="stylesheet" href="css/rider.css"><link rel="stylesheet" href="css/dashboard.css"><link rel="stylesheet" href="css/history.css"></head><body><main class="rider-shell rider-dashboard">
<header class="rider-top"><div><div class="rider-brand"><img src="../assets/branding/foodera-wordmark.png" alt="Foodera"></div><p class="rider-kicker">Foodera delivery</p><h1>Delivery history</h1></div><div class="rider-top-actions"><a class="rider-history-link" href="dashboard.php">Dashboard</a><a href="home.php">Manage deliveries</a><a href="logout.php">Sign out</a></div></header>
<section class="rider-performance-intro"><div><p class="rider-kicker">Your records</p><h2>Past delivery activity</h2><p>Private records of tasks assigned to you. Customer contact details and OTPs are not shown.</p></div><strong><?php echo $total; ?> records</strong></section>
<section class="rider-stat-grid"><article><span>Successfully delivered</span><strong><?php echo (int)$stats['delivered']; ?></strong></article><article><span>Reported issues</span><strong><?php echo (int)$stats['failed']; ?></strong></article><article><span>Average delivery time</span><strong><?php echo $stats['average_minutes'] === null ? '—' : (int)round($stats['average_minutes']).' min'; ?></strong></article></section>
<nav class="rider-history-tabs"><a href="history.php"<?php echo $status === 'all' ? ' aria-current="page"' : ''; ?>>All</a><a href="history.php?status=delivered"<?php echo $status === 'delivered' ? ' aria-current="page"' : ''; ?>>Delivered</a><a href="history.php?status=failed"<?php echo $status === 'failed' ? ' aria-current="page"' : ''; ?>>Issues</a></nav>
<section class="rider-card rider-dashboard-section"><div class="rider-section-heading"><div><h2><?php echo riderEscape($title); ?></h2><p>Most recent records first.</p></div></div><?php if (!$deliveries) { ?><p class="rider-empty-copy">No delivery records match this filter.</p><?php } else { ?><div class="rider-history-wrap"><table class="rider-history-table"><thead><tr><th>Order</th><th>Customer / area</th><th>Outcome</th><th>Payment</th><th>Value</th><th>Finished</th></tr></thead><tbody>
<?php foreach ($deliveries as $delivery) { $finished = $delivery['delivered_at'] ?: $delivery['assigned_at']; $outcome = ucwords(str_replace('_', ' ', $delivery['status'])); $collection = ucwords(str_replace('_', ' ', $delivery['collection_status'] ?? 'pending')); ?><tr><td><strong>#<?php echo (int)$delivery['orderid']; ?></strong><small>Assigned <?php echo date('d M, h:i A', strtotime($delivery['assigned_at'])); ?></small></td><td><strong><?php echo riderEscape($delivery['customer_name']); ?></strong><small><?php echo riderEscape($delivery['address']); ?></small></td><td><span class="rider-history-status <?php echo riderEscape($delivery['status']); ?>"><?php echo riderEscape($outcome); ?></span><?php if ($delivery['failure_reason']) { ?><small><?php echo riderEscape($delivery['failure_reason']); ?></small><?php } ?></td><td><?php echo riderEscape(strtoupper($delivery['payment_method'] ?? '')); ?><?php if (($delivery['payment_method'] ?? '') === 'cod') { ?><small class="rider-collection <?php echo riderEscape($delivery['collection_status'] ?? 'pending'); ?>">COD <?php echo riderEscape($collection); ?></small><?php } ?></td><td><strong>Rs <?php echo number_format((float)$delivery['total_amount']); ?></strong></td><td><strong><?php echo date('d M Y', strtotime($finished)); ?></strong><small><?php echo date('h:i A', strtotime($finished)); ?></small></td></tr><?php } ?></tbody></table></div><?php if ($pages > 1) { ?><nav class="rider-pagination"><?php if ($page > 1) { ?><a href="history.php?status=<?php echo urlencode($status); ?>&amp;page=<?php echo $page - 1; ?>">Previous</a><?php } ?><span>Page <?php echo $page; ?> of <?php echo $pages; ?></span><?php if ($page < $pages) { ?><a href="history.php?status=<?php echo urlencode($status); ?>&amp;page=<?php echo $page + 1; ?>">Next</a><?php } ?></nav><?php } } ?></section></main></body></html>
